		meta mark & 0x3f000000 == 0x00000000 numgen random mod 2 vmap { 0 : jump mwan3_or_meta_0x1000000, 1 : jump mwan3_or_meta_0x2000000 }
		meta mark & 0x3f000000 == 0x00000000 meta mark set meta mark & 0xfeffffff | 0x3e000000
	}
}
table inet mwan3 {
	chain mwan3_rules {
		udp dport 53 meta nfproto ipv4 meta mark & 0x3f000000 == 0x00000000 meta mark set meta mark | 0x3f000000
